from collections import deque


class Solution:
    def shortestPath(self, grid: list[list[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        if k >= m + n - 2:
            return m + n - 2                       # enough eliminations to walk the Manhattan path
        queue = deque([(0, 0, 0)])                 # (row, col, obstacles eliminated so far)
        seen = {(0, 0, 0)}
        steps = 0
        while queue:
            for _ in range(len(queue)):            # one BFS level = one step
                r, c, used = queue.popleft()
                if r == m - 1 and c == n - 1:
                    return steps
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < m and 0 <= nc < n:
                        nu = used + grid[nr][nc]   # stepping on an obstacle uses one elimination
                        if nu <= k and (nr, nc, nu) not in seen:
                            seen.add((nr, nc, nu))  # at most m * n * (k + 1) states
                            queue.append((nr, nc, nu))
            steps += 1
        return -1
